      const int column_mate = rotation_mate[column];
      const int row_mate = rotation_mate[row];
      const float column_c = rotation_c[column];
      const float column_s = rotation_s[column];
      const float row_c = rotation_c[row];
      const float row_s = rotation_s[row];
      const float own_row = fmaf(
          column_s, current_matrix[row * 32 + column_mate],
          column_c * current_matrix[tid]);
      const float mate_row = fmaf(
          column_s, current_matrix[row_mate * 32 + column_mate],
          column_c * current_matrix[row_mate * 32 + column]);
      next_matrix[tid] = fmaf(row_s, mate_row, row_c * own_row);
      next_vectors[tid] = fmaf(
          column_s, current_vectors[row * 32 + column_mate],
          column_c * current_vectors[tid]);
      __syncthreads();
      float* swap = current_matrix;
      current_matrix = next_matrix;
      next_matrix = swap;
      swap = current_vectors;
      current_vectors = next_vectors;
      next_vectors = swap;
