    values[static_cast<int64_t>(blockIdx.x) * 32 + tid] = keys[0];
    permutation[tid] = columns[0];
  }
  __syncthreads();
  vectors[matrix_offset + tid] =
      current_vectors[row * 32 + permutation[column]];
}

