__global__ void sort_eigenpairs32(float* vectors, float* values) {
  using WarpSort = cub::WarpMergeSort<float, 1, 32, int>;
  __shared__ typename WarpSort::TempStorage sort_storage;
  __shared__ int permutation[32];
  __shared__ float matrix_copy[32 * 32];

  const int tid = static_cast<int>(threadIdx.x);
  float* matrix = vectors + static_cast<int64_t>(blockIdx.x) * 32 * 32;
  float* eigenvalues = values + static_cast<int64_t>(blockIdx.x) * 32;

  if (tid < 32) {
    float keys[1] = {eigenvalues[tid]};
    int columns[1] = {tid};
    WarpSort(sort_storage).Sort(keys, columns, FloatLess{});
    eigenvalues[tid] = keys[0];
    permutation[tid] = columns[0];
  }
  for (int index = tid; index < 32 * 32; index += blockDim.x) {
    matrix_copy[index] = matrix[index];
  }
  __syncthreads();
  for (int index = tid; index < 32 * 32; index += blockDim.x) {
    const int row = index & 31;
    const int destination_column = index >> 5;
    matrix[index] = matrix_copy[permutation[destination_column] * 32 + row];
  }
}

__global__ void cyclic_jacobi32(
    const float* input, float* vectors, float* values, int rounds) {
  using WarpSort = cub::WarpMergeSort<float, 1, 32, int>;
  __shared__ float matrix[32 * 32];
  __shared__ float matrix_next[32 * 32];
  __shared__ float eigenvectors[32 * 32];
  __shared__ float eigenvectors_next[32 * 32];
  __shared__ float rotation_c[32];
  __shared__ float rotation_s[32];
  __shared__ int rotation_mate[32];
  __shared__ int permutation[32];
  __shared__ typename WarpSort::TempStorage sort_storage;

  const int tid = static_cast<int>(threadIdx.x);
  const int row = tid >> 5;
  const int column = tid & 31;
  const int64_t matrix_offset =
      static_cast<int64_t>(blockIdx.x) * 32 * 32;
  matrix[tid] = input[matrix_offset + tid];
  eigenvectors[tid] = row == column ? 1.0f : 0.0f;
  __syncthreads();
  float* current_matrix = matrix;
  float* next_matrix = matrix_next;
  float* current_vectors = eigenvectors;
  float* next_vectors = eigenvectors_next;

  for (int iteration = 0; iteration < rounds; ++iteration) {
      const int round = iteration % 31;
      if (tid < 16) {
        const int pair = tid;
        const int p = pair == 0 ? 31 : (round + pair) % 31;
        const int q = pair == 0 ? round : (round - pair + 31) % 31;
        const float app = current_matrix[p * 32 + p];
        const float aqq = current_matrix[q * 32 + q];
        const float apq = current_matrix[p * 32 + q];
        float cosine = 1.0f;
        float sine = 0.0f;
        if (fabsf(apq) > 2.0f * FLT_EPSILON *
                (1.0f + fabsf(app) + fabsf(aqq))) {
          const float tau = (aqq - app) / (2.0f * apq);
          const float tangent = copysignf(
              1.0f / (fabsf(tau) + sqrtf(fmaf(tau, tau, 1.0f))), tau);
          cosine = rsqrtf(1.0f + tangent * tangent);
          sine = tangent * cosine;
        }
        rotation_c[p] = cosine;
        rotation_c[q] = cosine;
        rotation_s[p] = -sine;
        rotation_s[q] = sine;
        rotation_mate[p] = q;
        rotation_mate[q] = p;
      }
      __syncthreads();

      const int column_mate = rotation_mate[column];
      const int row_mate = rotation_mate[row];
      const float column_c = rotation_c[column];
      const float column_s = rotation_s[column];
      const float row_c = rotation_c[row];
      const float row_s = rotation_s[row];
      const float own_row = fmaf(
          column_s, current_matrix[row * 32 + column_mate],
          column_c * current_matrix[tid]);
      const float mate_row = fmaf(
          column_s, current_matrix[row_mate * 32 + column_mate],
          column_c * current_matrix[row_mate * 32 + column]);
      next_matrix[tid] = fmaf(row_s, mate_row, row_c * own_row);
      next_vectors[tid] = fmaf(
          column_s, current_vectors[row * 32 + column_mate],
          column_c * current_vectors[tid]);
      __syncthreads();
      float* swap = current_matrix;
      current_matrix = next_matrix;
      next_matrix = swap;
      swap = current_vectors;
      current_vectors = next_vectors;
      next_vectors = swap;
  }

  if (tid < 32) {
    float keys[1] = {current_matrix[tid * 32 + tid]};
    int columns[1] = {tid};
    WarpSort(sort_storage).Sort(keys, columns, FloatLess{});
    values[static_cast<int64_t>(blockIdx.x) * 32 + tid] = keys[0];
    permutation[tid] = columns[0];
  }
  __syncthreads();
  vectors[matrix_offset + tid] =
      current_vectors[row * 32 + permutation[column]];
}

