      s.handle, CUSOLVER_EIG_MODE_VECTOR, CUBLAS_FILL_MODE_LOWER, n,
      vectors_col_major.data_ptr<float>(), n, values.data_ptr<float>(),
      s.workspace.data_ptr<float>(), s.lwork, s.info.data_ptr<int>(), s.params,
