    const float* input, const float* vectors, const float* values,
    int* flags, int batch) {
  constexpr int n = 32;
  constexpr int kGroupWidth = 8;
  __shared__ float shared_value_scale;
  const int matrix = static_cast<int>(blockIdx.x);
  const int tid = static_cast<int>(threadIdx.x);
  if (matrix >= batch) {
    return;
  }
  const int column = tid / kGroupWidth;
  const int group_lane = tid & (kGroupWidth - 1);
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;

  if (tid < n) {
    float value_scale = fabsf(values[vector_offset + tid]);
    for (int offset = 16; offset > 0; offset >>= 1) {
      value_scale = fmaxf(
          value_scale,
          __shfl_down_sync(0xffffffff, value_scale, offset));
    }
    if (tid == 0) {
      shared_value_scale = fmaxf(value_scale, 1.0e-30f);
    }
  }
  __syncthreads();

  float orthogonal_sum = 0.0f;
  float eigen_sum = 0.0f;
  const float eigenvalue = values[vector_offset + column];
