    float gram = 0.0f;
    float aq = 0.0f;
    for (int inner = group_lane; inner < n; inner += kGroupWidth) {
      gram = fmaf(
          vectors[matrix_offset + inner * n + row],
          vectors[matrix_offset + inner * n + column], gram);
      aq = fmaf(
          input[matrix_offset + row * n + inner],
          vectors[matrix_offset + inner * n + column], aq);
    }
    const unsigned int group_mask = __activemask();
    for (int offset = kGroupWidth / 2; offset > 0; offset >>= 1) {
      gram += __shfl_down_sync(group_mask, gram, offset, kGroupWidth);
      aq += __shfl_down_sync(group_mask, aq, offset, kGroupWidth);
    }
    if (group_lane == 0) {
      orthogonal_sum += fabsf(
          gram - static_cast<float>(row == column));
      eigen_sum += fabsf(
          aq - vectors[matrix_offset + row * n + column] * eigenvalue);
    }
  }

