std::vector<torch::Tensor> jacobi32(torch::Tensor input, int64_t rounds) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == 32 && input.size(2) == 32,
              "jacobi32 requires shape [batch, 32, 32]");
  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  auto vectors = torch::empty_like(input);
  auto values = torch::empty({input.size(0), 32}, input.options());
  DirectCertificateState& state = direct_certificate_state();
  if (state.device != input.get_device() || state.batch != batch) {
    state.device = input.get_device();
    state.batch = batch;
    state.flags = torch::empty(
        {batch + 1}, input.options().dtype(torch::kInt32));
  }
  state.flags.zero_();
  constexpr int shared_bytes = 4896 * sizeof(float);
  cudaFuncSetAttribute(fused_householder_eigh32,
                       cudaFuncAttributeMaxDynamicSharedMemorySize,
                       shared_bytes);
  fused_householder_eigh32<<<
      batch, 512, shared_bytes>>>(
      input.data_ptr<float>(), vectors.data_ptr<float>(),
      values.data_ptr<float>());
  flag_small_gaps32<<<batch, 32>>>(
      values.data_ptr<float>(), state.flags.data_ptr<int>(), batch);
  int unsafe = 0;
  const cudaError_t copy_status = cudaMemcpy(
      &unsafe, state.flags.data_ptr<int>() + batch, sizeof(int),
      cudaMemcpyDeviceToHost);
  TORCH_CHECK(copy_status == cudaSuccess,
              "failed to read n32 safety flag: ",
              cudaGetErrorString(copy_status));
  return unsafe ? xsyev_batched(input)
                : std::vector<torch::Tensor>{vectors, values};
}

